/**
 * Unit tests for IteratorUtils.collatedIterator(Comparator, Iterator, Iterator)
 */
public class IteratorUtils_collatedIterator_TriageGen2Test {

    @Test
    public void testCollatedIterator_EqualLength() {
        Comparator<Integer> comparator = Integer::compareTo;
        Iterator<Integer> iter1 = Arrays.asList(1, 3, 5).iterator();
        Iterator<Integer> iter2 = Arrays.asList(2, 4, 6).iterator();

        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, iter1, iter2);

        List<Integer> expected = Arrays.asList(1, 2, 3, 4, 5, 6);
        List<Integer> actual = IteratorUtils.toList(result);

        assertEquals("Iterators of equal length should be merged and sorted", expected, actual);
    }

    @Test
    public void testCollatedIterator_FirstLonger() {
        Comparator<Integer> comparator = Integer::compareTo;
        Iterator<Integer> iter1 = Arrays.asList(1, 3, 5, 7, 9).iterator();
        Iterator<Integer> iter2 = Arrays.asList(2, 4).iterator();

        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, iter1, iter2);

        List<Integer> expected = Arrays.asList(1, 2, 3, 4, 5, 7, 9);
        List<Integer> actual = IteratorUtils.toList(result);

        assertEquals("Should handle first iterator being longer", expected, actual);
    }

    @Test
    public void testCollatedIterator_SecondLonger() {
        Comparator<Integer> comparator = Integer::compareTo;
        Iterator<Integer> iter1 = Arrays.asList(1, 10).iterator();
        Iterator<Integer> iter2 = Arrays.asList(2, 3, 4, 5).iterator();

        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, iter1, iter2);

        List<Integer> expected = Arrays.asList(1, 2, 3, 4, 5, 10);
        List<Integer> actual = IteratorUtils.toList(result);

        assertEquals("Should handle second iterator being longer", expected, actual);
    }

    @Test
    public void testCollatedIterator_OneEmpty() {
        Comparator<Integer> comparator = Integer::compareTo;
        Iterator<Integer> iter1 = Arrays.asList(1, 2, 3).iterator();
        Iterator<Integer> iter2 = Arrays.asList().iterator();

        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, iter1, iter2);

        List<Integer> expected = Arrays.asList(1, 2, 3);
        List<Integer> actual = IteratorUtils.toList(result);

        assertEquals("Should handle one empty iterator", expected, actual);
    }

    @Test
    public void testCollatedIterator_BothEmpty() {
        Comparator<Integer> comparator = Integer::compareTo;
        Iterator<Integer> iter1 = Arrays.asList().iterator();
        Iterator<Integer> iter2 = Arrays.asList().iterator();

        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, iter1, iter2);

        assertFalse("Resulting iterator should be empty", result.hasNext());
    }

    @Test
    public void testCollatedIterator_WithDuplicates() {
        Comparator<Integer> comparator = Integer::compareTo;
        Iterator<Integer> iter1 = Arrays.asList(1, 2, 5).iterator();
        Iterator<Integer> iter2 = Arrays.asList(2, 3, 5).iterator();

        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, iter1, iter2);

        // Note: Collating iterator typically preserves all elements including duplicates
        List<Integer> expected = Arrays.asList(1, 2, 2, 3, 5, 5);
        List<Integer> actual = IteratorUtils.toList(result);

        assertEquals("Should preserve duplicates from both iterators", expected, actual);
    }

    @Test
    public void testCollatedIterator_StringComparator() {
        Comparator<String> comparator = String::compareTo;
        Iterator<String> iter1 = Arrays.asList("apple", "cherry").iterator();
        Iterator<String> iter2 = Arrays.asList("banana", "date").iterator();

        Iterator<String> result = IteratorUtils.collatedIterator(comparator, iter1, iter2);

        List<String> expected = Arrays.asList("apple", "banana", "cherry", "date");
        List<String> actual = IteratorUtils.toList(result);

        assertEquals("Should work correctly with String comparator", expected, actual);
    }

    @Test(expected = NullPointerException.class)
    public void testCollatedIterator_NullComparator() {
        Iterator<Integer> iter1 = Arrays.asList(1).iterator();
        Iterator<Integer> iter2 = Arrays.asList(2).iterator();
        // This tests behavior when comparator is null (implementation dependent, but usually throws NPE)
        IteratorUtils.collatedIterator(null, iter1, iter2);
    }
}
